const parse = (value, fallback = {}) => {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
};
const clean = (value) => String(value || '').trim();
const compact = (value) => clean(value).replace(/\s+/g, ' ').slice(0, 240);
const input = $input.first().json || {};
const resolucao = parse(input.resolucao_busca, {});
const contexto = parse(input.contexto_ia, {});
const entidadesContexto = contexto.entidades_ativas && typeof contexto.entidades_ativas === 'object'
  ? contexto.entidades_ativas : {};
const entidadesResolucao = resolucao.entidades_ativas && typeof resolucao.entidades_ativas === 'object'
  ? resolucao.entidades_ativas : {};
const estadoContexto = entidadesContexto.busca_empresarios && typeof entidadesContexto.busca_empresarios === 'object'
  ? entidadesContexto.busca_empresarios : null;
const mensagem = compact(input.pergunta);
const mostrarMais = resolucao.tipo_intencao === 'mostrar_mais_empresarios'
  || /\b(mostrar|ver|quero|mande|envie|exibir|exiba)\b.*\b(mais|restante|resto|outro|outros)\b/i.test(mensagem);
const continuarPendente = resolucao.modo_contexto === 'continuar_busca' && estadoContexto?.pendente && !mostrarMais;
const estado = mostrarMais || continuarPendente ? estadoContexto : null;
const entidades = { ...entidadesContexto, ...entidadesResolucao };
if (resolucao.modo_contexto === 'nova_busca') delete entidades.busca_empresarios;

let precisaClarificacao = Boolean(resolucao.precisa_clarificacao);
let perguntaBusca = compact(resolucao.consulta_semantica || resolucao.pergunta_busca || mensagem);
let necessidade = compact(resolucao.necessidade);
let categoria = compact(resolucao.categoria_servico);
let tentativas = Number(estado?.tentativas_clarificacao || 0);

if (estado?.pendente && !mostrarMais) {
  const termoInicial = compact(estado.termo_inicial);
  const consultaModelo = compact(resolucao.consulta_semantica || resolucao.pergunta_busca);
  const respostaRefinamento = necessidade || mensagem;
  perguntaBusca = consultaModelo && consultaModelo !== mensagem
    ? consultaModelo
    : compact([termoInicial, respostaRefinamento].filter(Boolean).join('. '));
  categoria = categoria || compact(estado.categoria);
  necessidade = necessidade || mensagem;
  tentativas = 1;
  precisaClarificacao = false;
}

let acao = 'pesquisar';
if (mostrarMais) acao = 'mostrar_mais';
else if (precisaClarificacao) acao = 'clarificar';

return [{ json: {
  ...input,
  resolucao,
  contexto,
  entidades,
  estado_busca: estado,
  acao,
  pergunta_busca: perguntaBusca || mensagem,
  necessidade: necessidade || null,
  categoria: categoria || null,
  tentativas_clarificacao: tentativas,
  pergunta_clarificacao: clean(resolucao.pergunta_clarificacao)
    || 'Perfeito. Descreva melhor o serviço que procura ou o problema que precisa resolver.'
} }];

const r = $('Preparar pesquisa').first().json;
const busca = {
  pendente: true,
  termo_inicial: r.estado_busca?.termo_inicial || r.pergunta,
  categoria: r.categoria || null,
  pergunta_clarificacao: r.pergunta_clarificacao,
  tentativas_clarificacao: 1,
  criada_em: r.estado_busca?.criada_em || new Date().toISOString(),
  expira_em: new Date(Date.now() + 60 * 60 * 1000).toISOString()
};
const entidades = { ...r.entidades, busca_empresarios: busca, tipo_intencao: 'busca_servico', dominio_busca: 'empresarios' };
return [{ json: {
  _tipo: 'sem_chunks', conteudo: null, _dominio: 'empresarios', _rag_contextual: false,
  consultar_base_conhecimento: false, tipo_intencao: 'clarificacao', metodo_busca: 'nenhum',
  sessao_token: r.sessao_token, contexto_ia: r.contexto, resolucao_busca: { ...r.resolucao, precisa_clarificacao: true, pergunta_clarificacao: r.pergunta_clarificacao, entidades_ativas: entidades },
  pergunta_busca: r.pergunta_busca, pergunta_original: r.pergunta,
  precisa_clarificacao: true, pergunta_clarificacao: r.pergunta_clarificacao,
  assunto_ativo: 'pesquisa de empresários', entidades_ativas: entidades,
  documentos: [], total_tokens_contexto_busca: Number(r.resolucao.total_tokens_resolucao_busca || 0)
} }];

const parse = (value, fallback = []) => {
  if (!value) return fallback;
  if (Array.isArray(value)) return value;
  if (typeof value === 'object' && value.data !== undefined) return parse(value.data, fallback);
  try { return JSON.parse(value); } catch { return fallback; }
};
const r = $('Preparar pesquisa').first().json;
const estado = r.estado_busca;
if (!estado?.resultados?.length) {
  const entidades = { ...r.entidades, tipo_intencao: 'busca_servico', dominio_busca: 'empresarios' };
  return [{ json: { _tipo: 'sem_chunks', conteudo: null, _dominio: 'empresarios', _rag_contextual: false,
    consultar_base_conhecimento: false, tipo_intencao: 'clarificacao', metodo_busca: 'nenhum', sessao_token: r.sessao_token,
    contexto_ia: r.contexto, pergunta_busca: r.pergunta, pergunta_original: r.pergunta, precisa_clarificacao: true,
    pergunta_clarificacao: 'Faça primeiro uma pesquisa de serviço para eu poder mostrar os demais resultados.', assunto_ativo: 'pesquisa de empresários',
    entidades_ativas: entidades, resolucao_busca: { ...r.resolucao, precisa_clarificacao: true, pergunta_clarificacao: 'Faça primeiro uma pesquisa de serviço para eu poder mostrar os demais resultados.', entidades_ativas: entidades },
    documentos: [], total_tokens_contexto_busca: Number(r.resolucao.total_tokens_resolucao_busca || 0) } }];
}
const validos = parse($input.first().json?.data ?? $input.first().json, []);
const porId = new Map(validos.map((item) => [item.servico_id, item]));
const TAMANHO_PAGINA = 5;
const inicio = Number(estado.exibidos || 0);
const fim = Math.min(inicio + TAMANHO_PAGINA, estado.resultados.length);
const pagina = estado.resultados.slice(inicio, fim);
const restantesOrdenados = pagina.map((ref) => ({ ...porId.get(ref.servico_id), ...ref })).filter((item) => item.servico_id && porId.has(item.servico_id));
const atualizado = { ...estado, exibidos: fim };
const entidades = { ...r.entidades, busca_empresarios: atualizado, tipo_intencao: 'mostrar_mais_empresarios', dominio_busca: 'empresarios' };
const metadata = { _dominio: 'empresarios', _rag_contextual: true, consultar_base_conhecimento: true,
  tipo_intencao: 'mostrar_mais_empresarios', metodo_busca: 'continuidade', sessao_token: r.sessao_token, contexto_ia: r.contexto,
  pergunta_busca: estado.consulta || r.pergunta, pergunta_original: r.pergunta, precisa_clarificacao: false, assunto_ativo: 'pesquisa de empresários',
  entidades_ativas: entidades, total_resultados_empresarios: restantesOrdenados.length,
  total_restantes_empresarios: Math.max(0, estado.resultados.length - fim),
  total_tokens_contexto_busca: Number(r.resolucao.total_tokens_resolucao_busca || 0), resolucao_busca: { ...r.resolucao, entidades_ativas: entidades } };
if (!restantesOrdenados.length) return [{ json: { _tipo: 'sem_chunks', conteudo: null, ...metadata } }];
return restantesOrdenados.map((item) => ({ json: { ...item, ...metadata,
  ordem_exibicao: item.ordem, chunk_id: item.servico_id, base_conhecimento_id: item.servico_id,
  documento_titulo: [item.servico, item.empresa].filter(Boolean).join(' — '), score_documento: item.score, score: item.score,
  chunk_index: 0, origem: 'diretorio_empresarios_continuacao',
  conteudo: ['Nome: ' + (item.nome || ''), 'Empresa: ' + (item.empresa || ''), 'Serviço: ' + (item.servico || ''),
    'Categoria: ' + (item.categoria || ''), 'Descrição: ' + (item.descricao || ''),
    item.site ? 'Site: ' + item.site : '', item.telefone ? 'Telefone: ' + item.telefone : '', item.email ? 'E-mail: ' + item.email : '',
    item.instagram ? 'Instagram: ' + item.instagram : '', item.linkedin ? 'LinkedIn: ' + item.linkedin : ''].filter(Boolean).join('\n')
} }));

const r = $('Preparar pesquisa').first().json;
const ranking = $('Aplicar reranking').first().json || {};
const todos = (Array.isArray(ranking.candidatos) ? ranking.candidatos : [])
  .map((item, index) => ({ ...item, ordem_exibicao: index + 1 }));
const exibidos = todos.slice(0, 5);
const refs = todos.map((item, index) => ({ servico_id: item.servico_id, ordem: index + 1, score: item.score }));
const busca = {
  pendente: false,
  consulta: r.pergunta_busca,
  categoria: r.categoria || null,
  resultados: refs,
  exibidos: exibidos.length,
  total: todos.length,
  criada_em: new Date().toISOString(),
  expira_em: new Date(Date.now() + 60 * 60 * 1000).toISOString()
};
const entidades = { ...r.entidades, busca_empresarios: busca, tipo_intencao: 'busca_servico', dominio_busca: 'empresarios' };
const restantes = Math.max(0, todos.length - exibidos.length);
const metadata = {
  _dominio: 'empresarios', _rag_contextual: true, consultar_base_conhecimento: true,
  tipo_intencao: 'busca_servico', metodo_busca: 'hibrido_com_reranking', sessao_token: r.sessao_token,
  contexto_ia: r.contexto, pergunta_busca: r.pergunta_busca, pergunta_original: r.pergunta,
  precisa_clarificacao: false, pergunta_clarificacao: null, assunto_ativo: 'pesquisa de empresários',
  entidades_ativas: entidades, total_resultados_empresarios: todos.length,
  total_restantes_empresarios: restantes,
  total_tokens_contexto_busca: Number(r.resolucao.total_tokens_resolucao_busca || 0)
    + Number($('Gerar embedding da pesquisa').first().json.usage?.total_tokens || 0)
    + Number(ranking.total_tokens_reranking || 0),
  resolucao_busca: { ...r.resolucao, dominio_busca: 'empresarios', entidades_ativas: entidades }
};
if (!exibidos.length) return [{ json: { _tipo: 'sem_chunks', conteudo: null, ...metadata } }];
return exibidos.map((item) => ({ json: {
  ...item, ...metadata,
  chunk_id: item.servico_id, base_conhecimento_id: item.servico_id,
  documento_titulo: [item.servico, item.empresa].filter(Boolean).join(' — '),
  score_documento: item.score, chunk_index: 0, origem: 'catalogo_servicos_rerankeado',
  conteudo: [
    'Nome: ' + (item.nome || ''), 'Empresa: ' + (item.empresa || ''),
    'Serviço: ' + (item.servico || ''), 'Categoria informada: ' + (item.categoria || ''),
    'Descrição: ' + (item.descricao || ''),
    item.problemas_resolvidos ? 'Problemas atendidos: ' + item.problemas_resolvidos : '',
    item.site ? 'Site: ' + item.site : '', item.telefone ? 'Telefone: ' + item.telefone : '',
    item.email ? 'E-mail: ' + item.email : '', item.instagram ? 'Instagram: ' + item.instagram : '',
    item.linkedin ? 'LinkedIn: ' + item.linkedin : ''
  ].filter(Boolean).join('\n')
} }));

const parse = (value, fallback = []) => {
  if (!value) return fallback;
  if (Array.isArray(value)) return value;
  if (typeof value === 'object' && value.data !== undefined) return parse(value.data, fallback);
  try { return JSON.parse(value); } catch { return fallback; }
};
const raw = $input.first().json?.data ?? $input.first().json;
const candidatos = parse(raw, []).slice(0, 30);
if (!candidatos.length) return [{ json: { candidatos: [], body: null } }];
const necessidade = $('Preparar pesquisa').first().json.pergunta_busca;
const documentos = candidatos.map((item) => ({
  servico_id: item.servico_id,
  empresa: item.empresa || '',
  servico: item.servico || '',
  categoria_informada: item.categoria || '',
  descricao: String(item.descricao || '').slice(0, 700),
  problemas_resolvidos: String(item.problemas_resolvidos || '').slice(0, 500),
  especialidades: Array.isArray(item.especialidades) ? item.especialidades.slice(0, 12) : []
}));
const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    resultados: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        properties: {
          servico_id: { type: 'string' },
          score: { type: 'integer', minimum: 0, maximum: 100 }
        },
        required: ['servico_id', 'score']
      }
    }
  },
  required: ['resultados']
};
const body = {
  model: 'google/gemini-2.5-flash', temperature: 0, max_tokens: 1600,
  reasoning: { enabled: false },
  response_format: { type: 'json_schema', json_schema: { name: 'elo_reranking_servicos', strict: true, schema } },
  messages: [
    { role: 'system', content: [
      'Você é o reranker da pesquisa de serviços da Elo Connect.',
      'Compare a necessidade somente com as informações explícitas de cada oferta.',
      'Não presuma serviços que não estejam descritos e não use reputação, religião ou atributos pessoais.',
      'Atribua de 0 a 100 para a capacidade real da oferta resolver a necessidade.',
      '0 a 20 significa incompatível; 21 a 49 significa evidência insuficiente; 50 a 79 significa compatível; 80 a 100 significa correspondência direta.',
      'Retorne todos os servico_id recebidos exatamente uma vez e não invente identificadores.'
    ].join('\n') },
    { role: 'user', content: JSON.stringify({ necessidade, candidatos: documentos }) }
  ]
};
return [{ json: { candidatos, body } }];

const clean = (value) => String(value || '').trim();
const parseJson = (value) => {
  if (value && typeof value === 'object') return value;
  const text = clean(value).replace(/```json|```/g, '').trim();
  try { return JSON.parse(text); } catch {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch {} }
  return null;
};
const preparado = $('Preparar reranking').first().json || {};
const candidatos = Array.isArray(preparado.candidatos) ? preparado.candidatos : [];
if (!candidatos.length) return [{ json: { candidatos: [], total_tokens_reranking: 0 } }];
const resposta = $input.first().json || {};
const parsed = parseJson(resposta.choices?.[0]?.message?.content);
if (!parsed || !Array.isArray(parsed.resultados)) throw new Error('O reranker não retornou JSON válido.');
const porId = new Map(candidatos.map((item) => [String(item.servico_id), item]));
const pontuados = parsed.resultados
  .map((item) => {
    const candidato = porId.get(String(item.servico_id));
    if (!candidato) return null;
    const score = Math.max(0, Math.min(100, Number(item.score)));
    if (!Number.isFinite(score)) return null;
    return { ...candidato, score_rerank: score, score: score / 100 };
  })
  .filter((item) => item && item.score_rerank >= 50)
  .sort((a, b) => {
    if (b.score_rerank !== a.score_rerank) return b.score_rerank - a.score_rerank;
    const da = Date.parse(a.cadastro_criado_em || '') || Number.MAX_SAFE_INTEGER;
    const db = Date.parse(b.cadastro_criado_em || '') || Number.MAX_SAFE_INTEGER;
    if (da !== db) return da - db;
    return String(a.cadastro_id).localeCompare(String(b.cadastro_id));
  });
const normalizarEmpresa = (value) => clean(value)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const vistos = new Set();
const unicos = pontuados.filter((item) => {
  const empresa = normalizarEmpresa(item.empresa);
  const id = empresa ? `empresa:${empresa}` : `cadastro:${String(item.cadastro_id)}`;
  if (vistos.has(id)) return false;
  vistos.add(id);
  return true;
});
return [{ json: { candidatos: unicos, total_tokens_reranking: Number(resposta.usage?.total_tokens || 0) } }];
